using System.Security.Claims; using LogbookSqlServer.Data; using LogbookSqlServer.Models; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace LogbookSqlServer.Controllers;
[ApiController][Route("api/auth")] public class AuthController(LogbookDbContext db,IPasswordHasher<AppUser> hasher):ControllerBase {
 public record LoginRequest(string Username,string Password);
 [HttpPost("login")] public async Task<IActionResult> Login(LoginRequest r){if(string.IsNullOrWhiteSpace(r.Username)||string.IsNullOrEmpty(r.Password))return BadRequest(new{message="กรุณากรอกชื่อผู้ใช้และรหัสผ่าน"});var u=await db.Users.SingleOrDefaultAsync(x=>x.Username==r.Username.Trim());if(u is null||hasher.VerifyHashedPassword(u,u.PasswordHash,r.Password)==PasswordVerificationResult.Failed)return Unauthorized(new{message="ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง"});var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim("DisplayName",u.DisplayName),new Claim(ClaimTypes.Role,u.Role)};await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)),new AuthenticationProperties{IsPersistent=true,ExpiresUtc=DateTimeOffset.UtcNow.AddHours(8)});return Ok(new{username=u.Username,displayName=u.DisplayName,role=u.Role});}
 [HttpPost("logout")] public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return Ok(new{message="ออกจากระบบแล้ว"});}
 [HttpGet("me")] public IActionResult Me()=>User.Identity?.IsAuthenticated==true?Ok(new{username=User.Identity.Name,displayName=User.FindFirst("DisplayName")?.Value,role=User.FindFirst(ClaimTypes.Role)?.Value}):Unauthorized();
}